ing effective state management and data validation.","tree":{"sha":"07df1ad046e4aef82e61aa1fb19608e1111e30c7","url":"https://api.github.com/repos/Harikeshav-R/Sprout/git/trees/07df1ad046e4aef82e61aa1fb19608e1111e30c7"},"url":"https://api.github.com/repos/Harikeshav-R/Sprout/git/commits/2ab94c03b0079b240a4d4cb9bf144238697ceec0","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/63719951?v=4","events_url":"https://api.github.com/users/Harikeshav-R/events{/privacy}","followers_url":"https://api.github.com/users/Harikeshav-R/followers","following_url":"https://api.github.com/users/Harikeshav-R/following{/other_user}","gists_url":"https://api.github.com/users/Harikeshav-R/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Harikeshav-R","id":63719951,"login":"Harikeshav-R","node_id":"MDQ6VXNlcjYzNzE5OTUx","organizations_url":"https://api.github.com/users/Harikeshav-R/orgs","received_events_url":"https://api.github.com/users/Harikeshav-R/received_events","repos_url":"https://api.github.com/users/Harikeshav-R/repos","site_admin":false,"starred_url":"https://api.github.com/users/Harikeshav-R/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Harikeshav-R/subscriptions","type":"User","url":"https://api.github.com/users/Harikeshav-R","user_view_type":"public"},"html_url":"https://github.com/Harikeshav-R/Sprout/commit/2ab94c03b0079b240a4d4cb9bf144238697ceec0","node_id":"C_kwDORViF0doAKDJhYjk0YzAzYjAwNzliMjQwYTRkNGNiOWJmMTQ0MjM4Njk3Y2VlYzA","parents":[{"html_url":"https://github.com/Harikeshav-R/Sprout/commit/2f4622192aec30de7348554f3aefbbeeaa940b62","sha":"2f4622192aec30de7348554f3aefbbeeaa940b62","url":"https://api.github.com/repos/Harikeshav-R/Sprout/commits/2f4622192aec30de7348554f3aefbbeeaa940b62"}],"sha":"2ab94c03b0079b240a4d4cb9bf144238697ceec0","url":"https://api.github.com/repos/Harikeshav-R/Sprout/commits/2ab94c0